import ast

def score(program: str) -> float:
    try:
        tree = ast.parse(program)
    except:
        return 0.0

    # Must have score function
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name == "score":
            break
    else:
        return 0.0

    # Score by program complexity
    nodes = len(list(ast.walk(tree)))
    return max(0.0, min(1.0, 0.2 + nodes * 0.003))

